// packages/analytics/src/registry/generate.ts
//
// Registry → code generator. Outputs are COMMITTED; drift is a test failure
// (generate.test.ts) and a CLI check (`npm run registry:check`). Never edit
// files under generated/ by hand.
//
// CLI:
//   npx tsx src/registry/generate.ts                  # write generated files
//   npx tsx src/registry/generate.ts --check          # exit 1 on drift
//   npx tsx src/registry/generate.ts --write-baseline # accept registry as baseline

import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import type { EventDef } from './types';
import { EVENTS } from './events/index';
import type { BaselineDoc } from './lint';

export const REGISTRY_DIR = path.dirname(fileURLToPath(import.meta.url));
export const GENERATED_DIR = path.join(REGISTRY_DIR, 'generated');
export const BASELINE_PATH = path.join(REGISTRY_DIR, 'baseline.json');
export const FIXTURES_PATH = path.join(REGISTRY_DIR, 'fixtures.json');

const GENERATED_HEADER =
  '// AUTO-GENERATED by src/registry/generate.ts — DO NOT EDIT.\n' +
  '// Regenerate: npx tsx src/registry/generate.ts\n' +
  '// Drift check: npx tsx src/registry/generate.ts --check (also enforced by tests)\n';

function byName(events: EventDef[]): EventDef[] {
  return [...events].sort((a, b) => a.name.localeCompare(b.name));
}

// ─── event-types.ts ──────────────────────────────────────────────────────────

function buildEventTypes(events: EventDef[]): string {
  const sorted = byName(events);
  const lines: string[] = [GENERATED_HEADER];
  lines.push("import type { EventDef } from '@navdhya/analytics/src/registry/types';");
  lines.push('');
  lines.push('export const EVENT_NAMES = [');
  for (const e of sorted) lines.push(`  '${e.name}',`);
  lines.push('] as const;');
  lines.push('');
  lines.push('export type EventName = (typeof EVENT_NAMES)[number];');
  lines.push('');
  lines.push('/** Required params are non-optional; optional params are `?`. */');
  lines.push('export interface EventParamMap {');
  for (const e of sorted) {
    const fields = e.params
      .map((p) => `${p.name}${p.required ? '' : '?'}: ${p.type}`)
      .join('; ');
    lines.push(`  ${e.name}: { ${fields} };`);
  }
  lines.push('}');
  lines.push('');
  lines.push('export type EventParams<E extends EventName> = EventParamMap[E];');
  lines.push('');
  lines.push('/** JSON snapshot of the registry — source of truth for runtime checks. */');
  lines.push('export const EVENT_DEFS: Readonly<Record<EventName, EventDef>> = ');
  lines.push(JSON.stringify(Object.fromEntries(sorted.map((e) => [e.name, e])), null, 2));
  lines.push(';');
  lines.push('');
  return lines.join('\n');
}

// ─── validator.ts ────────────────────────────────────────────────────────────

function buildValidator(events: EventDef[]): string {
  const sorted = byName(events);
  const lines: string[] = [GENERATED_HEADER];
  lines.push('/**');
  lines.push(' * Fail-closed event-param validation against the registry.');
  lines.push(' * Returns [] when valid; one message per violation (unknown events and');
  lines.push(' * unknown params are violations — allowlists only).');
  lines.push(' */');
  lines.push('export function validateEventParams(name: string, params: Record<string, unknown>): string[] {');
  lines.push('  const errors: string[] = [];');
  lines.push('  switch (name) {');
  for (const e of sorted) {
    lines.push(`    case '${e.name}': {`);
    const allowed = JSON.stringify(e.params.map((p) => p.name));
    lines.push(`      const allowed = ${allowed};`);
    for (const p of e.params) {
      if (p.required) {
        lines.push(
          `      if (typeof params['${p.name}'] !== '${p.type}') errors.push('${e.name}.${p.name}: expected ${p.type} (required)');`,
        );
      } else {
        lines.push(
          `      if ('${p.name}' in params && typeof params['${p.name}'] !== '${p.type}') errors.push('${e.name}.${p.name}: expected ${p.type}');`,
        );
      }
    }
    lines.push('      for (const k of Object.keys(params)) {');
    lines.push('        if (!allowed.includes(k)) {');
    lines.push(`          errors.push('${e.name}: unknown param "' + k + '"');`);
    lines.push('        }');
    lines.push('      }');
    lines.push('      break;');
    lines.push('    }');
  }
  lines.push('    default:');
  lines.push("      errors.push('unknown event \"' + name + '\"');");
  lines.push('  }');
  lines.push('  return errors;');
  lines.push('}');
  lines.push('');
  return lines.join('\n');
}

// ─── schemas.json ────────────────────────────────────────────────────────────

function buildSchemas(events: EventDef[]): string {
  const sorted = byName(events);
  const out: Record<string, unknown> = {
    $comment: 'AUTO-GENERATED by src/registry/generate.ts — DO NOT EDIT.',
    events: {} as Record<string, unknown>,
  };
  const evs = out.events as Record<string, unknown>;
  for (const e of sorted) {
    evs[e.name] = {
      priority: e.priority,
      producer: e.producer,
      surfaces: e.surfaces,
      allowedSinks: e.allowedSinks,
      params: {
        type: 'object',
        additionalProperties: false,
        required: e.params.filter((p) => p.required).map((p) => p.name),
        properties: Object.fromEntries(e.params.map((p) => [p.name, { type: p.type, description: p.description }])),
      },
    };
  }
  return JSON.stringify(out, null, 2) + '\n';
}

// ─── bigquery-docs.md ────────────────────────────────────────────────────────

function esc(s: string): string {
  return s.replace(/\|/g, '\\|');
}

function buildBqDocs(events: EventDef[]): string {
  const sorted = byName(events);
  const lines: string[] = [
    '<!-- AUTO-GENERATED by src/registry/generate.ts — DO NOT EDIT. -->',
    '',
    '# Signal events — BigQuery column reference',
    '',
    'Column contract for `signals_raw.params`. Envelope columns (id, name, version,',
    'occurredAt, receivedAt, surface, appVersion, session.id, session.seq, actor.uidHash,',
    'actor.anonId, consent, context, source) are documented in the plan doc §B2.',
    '',
  ];
  for (const e of sorted) {
    lines.push(`## \`${e.name}\` (v${e.version})`);
    lines.push('');
    lines.push(`- **Owner:** ${e.owner} · **Producer:** ${e.producer} · **Priority:** ${e.priority}`);
    lines.push(`- **Surfaces:** ${e.surfaces.join(', ')}`);
    lines.push(`- **Sinks:** ${e.allowedSinks.join(', ')}`);
    lines.push(`- **Privacy:** ${e.privacyClass} · **Retention:** ${e.retentionClass} · **Sampling:** ${e.sampling.mode}${e.sampling.rate !== undefined ? ` @ ${e.sampling.rate}` : ''}`);
    lines.push(`- ${e.description}`);
    lines.push('');
    lines.push('| Param | Type | Required | Description |');
    lines.push('|---|---|---|---|');
    for (const p of e.params) {
      lines.push(`| \`${p.name}\` | ${p.type} | ${p.required ? 'yes' : 'no'} | ${esc(p.description)} |`);
    }
    lines.push('');
  }
  return lines.join('\n');
}

// ─── orchestration ───────────────────────────────────────────────────────────

export const GENERATED_FILES = ['event-types.ts', 'validator.ts', 'schemas.json', 'bigquery-docs.md'] as const;

export function generateAll(events: EventDef[]): Map<string, string> {
  const out = new Map<string, string>();
  out.set('event-types.ts', buildEventTypes(events));
  out.set('validator.ts', buildValidator(events));
  out.set('schemas.json', buildSchemas(events));
  out.set('bigquery-docs.md', buildBqDocs(events));
  return out;
}

export function writeGenerated(events: EventDef[]): string[] {
  fs.mkdirSync(GENERATED_DIR, { recursive: true });
  const written: string[] = [];
  for (const [file, content] of generateAll(events)) {
    const target = path.join(GENERATED_DIR, file);
    fs.writeFileSync(target, content, 'utf8');
    written.push(file);
  }
  return written;
}

/** Returns drift descriptions; empty array = generated output matches the repo. */
export function checkGenerated(events: EventDef[]): string[] {
  const drift: string[] = [];
  for (const [file, content] of generateAll(events)) {
    const target = path.join(GENERATED_DIR, file);
    if (!fs.existsSync(target)) {
      drift.push(`${file}: missing`);
      continue;
    }
    const onDisk = fs.readFileSync(target, 'utf8');
    if (onDisk !== content) drift.push(`${file}: differs from registry output`);
  }
  return drift;
}

export function buildBaseline(events: EventDef[]): BaselineDoc {
  const doc: BaselineDoc = { events: {} };
  for (const e of byName(events)) {
    doc.events[e.name] = { version: e.version, params: Object.fromEntries(e.params.map((p) => [p.name, p.type])) };
  }
  return doc;
}

export function readBaseline(): BaselineDoc | undefined {
  if (!fs.existsSync(BASELINE_PATH)) return undefined;
  return JSON.parse(fs.readFileSync(BASELINE_PATH, 'utf8')) as BaselineDoc;
}

export function readFixtures(): unknown[] {
  if (!fs.existsSync(FIXTURES_PATH)) return [];
  const doc = JSON.parse(fs.readFileSync(FIXTURES_PATH, 'utf8')) as { fixtures: unknown[] };
  return doc.fixtures;
}

export function writeBaseline(events: EventDef[]): void {
  fs.writeFileSync(BASELINE_PATH, JSON.stringify(buildBaseline(events), null, 2) + '\n', 'utf8');
}

// ─── CLI ─────────────────────────────────────────────────────────────────────

function main(argv: string[]): number {
  if (argv.includes('--write-baseline')) {
    writeBaseline(EVENTS);
    process.stdout.write(`baseline written: ${path.relative(process.cwd(), BASELINE_PATH)}\n`);
    return 0;
  }
  if (argv.includes('--check')) {
    const drift = checkGenerated(EVENTS);
    if (drift.length > 0) {
      process.stderr.write(`registry drift detected:\n${drift.map((m) => `  - ${m}`).join('\n')}\nrun: npx tsx src/registry/generate.ts\n`);
      return 1;
    }
    process.stdout.write('registry: generated output in sync\n');
    return 0;
  }
  const written = writeGenerated(EVENTS);
  process.stdout.write(`generated: ${written.join(', ')}\n`);
  return 0;
}

const invokedDirectly =
  process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href;
if (invokedDirectly) {
  process.exit(main(process.argv.slice(2)));
}
